base = 0
previous_slips = payslip.env['hr.payslip'].search([('employee_id', '=', employee.id), ('state', 'in', ['done', 'paid'])], order= 'create_date desc', limit=1)
for slip in previous_slips:
    for line in slip.line_ids.filtered(lambda l: l.category_id.code == 'BASIC'):
        base += line.total

# Check if using automatic corrections (worked_days) or manual input
correction_lines = payslip.worked_days_line_ids.filtered(lambda w: w.is_correction)

if correction_lines:
    # Automatic corrections from l10n_pt_hr_payroll_auto_corrections module
    entries_discount = entries_to_discount_wage(payslip)
    if contract.time_credit:
        worked_hours = 0
        for line in correction_lines:
            hours = line.number_of_hours
            # Apply negative sign for entries that discount
            if line.work_entry_type_id.code in entries_discount:
                worked_hours -= hours
            else:
                worked_hours += hours
        worked_days = int(worked_hours / 6)
        surplus = worked_hours % 6
        if surplus > 3:
            worked_days += 1
        elif surplus <= 3:
            worked_days += 0.5
    else:
        worked_days = 0
        for line in correction_lines:
            days = line.number_of_days
            # Apply negative sign for entries that discount
            if line.work_entry_type_id.code in entries_discount:
                worked_days -= days
            else:
                worked_days += days
elif 'BASIC_CORR_DAYS' in inputs:
    # Manual input when auto_corrections module not installed
    worked_days = inputs['BASIC_CORR_DAYS'].amount
else:
    worked_days = 0

result = (base / 30) * worked_days

